#!/usr/bin/env node

"use strict";

const crypto = require("crypto");
const fs = require("fs");
const parseArgs = require("minimist");
const syslog = require("modern-syslog");

let args = process.argv.slice(2);
let argv = parseArgs(args);

function usage() {
    console.log("Usage:", process.argv[1], "[options]");
    console.log("");
    console.log("OPTIONS:");
    console.log("  -h,--help                print this message");
    console.log("  --id STRING              Unique ID of update");
    console.log("  --url URL                URL to retrieve");
    console.log("  --destination FILE       destination for file");
    console.log("  --shasum CSUM            SHA1 checksum");
}

if (argv.h || argv.help) {
    usage();
    process.exit(0);
}

if (!argv.id) {
    console.log("ERROR: id not specified!");
    usage();
    process.exit(1);
}

if (!argv.url) {
    console.log("ERROR: url not specified!");
    usage();
    process.exit(1);
}

if (!argv.destination) {
    console.log("ERROR: destination not specified!");
    usage();
    process.exit(1);
}

if (!argv.shasum) {
    console.log("ERROR: shasum not specified");
    usage();
    process.exit(1);
}

syslog.init("jibo-download-update", syslog.LOG_PID | syslog.LOG_ODELAY, syslog.LOG_LOCAL0);

syslog.info("Downloading %s to %s", argv.url, argv.destination);

let fstream = fs.createWriteStream(argv.destination, {defaultEncoding: "binary"});

let hash = crypto.createHash("sha1");

let progress = {
    id: argv.id,
    length: null,
    received: 0,
    status: "uninitialized"
};

function writeProgress(skipSyslog) {
    if (progress.status == "downloading" && !skipSyslog) {
        syslog.info("Received %d/%d bytes (%s %%)", progress.received, progress.length, (progress.percent).toFixed(2));
    }
    console.log(JSON.stringify(progress));
}

let http = require("http");
if (argv.url.startsWith("https:")) {
    http = require("https");
}

let req = http.get(argv.url, function(res) {
    if (res.statusCode != 200) {
        progress.status = "failed";
        progress.reason = http.STATUS_CODES[res.statusCode];
        writeProgress();
        syslog.error("Failed to GET: %s", progress.reason);
        process.exit(1);
    }
    progress.length = parseInt(res.headers["content-length"]);
    progress.status = "initialized";
    writeProgress();

    let last_progress_percent = -100;
    let last_progress_time = Date.now();
    let last_progress_received = 0;
    // write progress, triggered on these conditions:
    // 1. every 10 percent
    // 2. every 5 seconds
    res.on("data", function(chunk) {
        hash.update(chunk, "binary");
        fstream.write(chunk);
        progress.received += chunk.length;
        progress.status = "downloading";
        progress.percent = (progress.received / progress.length) * 100;
        let now = Date.now();
        if (progress.received - last_progress_received > 25000) {
            writeProgress(true);
            last_progress_received = progress.received;
        }
        if ((progress.percent - last_progress_percent > 10)
            || (now - last_progress_time > 5000)) {
            writeProgress();
            last_progress_time = now;
            last_progress_percent = progress.percent;
        }
    });
    res.on("end", function() {
        fstream.end();
        let csum = hash.digest("hex");
        if (csum != argv.shasum) {
            progress.status = "failed";
            progress.reason = "checksum does not match";
            writeProgress();
            fs.unlinkSync(argv.destination);
            syslog.error("Download failed; checksum %s != %s", csum, argv.shasum)
            process.exit(1);
        } else {
            progress.status = "finished";
            writeProgress();
            syslog.info("Download completed successfully (%d bytes)", progress.length);
        }
    });
    res.on("error", function(error) {
        progress.status = "failed";
        progress.reason = error.message;
        writeProgress();
        fs.unlinkSync(argv.destination);
        syslog.error("Download failed:", error.message);
        syslog.error(error.stack);
        process.exit(1);
    });
});
req.setTimeout(120000);

req.on("error", function(e) {
    progress.status = "failed";
    progress.reason = e.code;
    writeProgress();
    process.exit(1);
});

req.on("timeout", function() {
    req.abort();
    progress.status = "failed";
    progress.reason = "timeout";
    writeProgress();
    process.exit(1);
});

process.on("uncaughtException", function(error) {
    progress.status = "failed";
    progress.reason = error.message;
    writeProgress();
    syslog.error("Uncaught exception:", error.message);
    syslog.error(error.stack);
    process.exit(1);
});
